function renderSpeechTranscript(text,box){
 const wrap=document.createElement('div');wrap.className='speech-player';
 const progress=document.createElement('progress');progress.className='speech-progress';progress.max=Math.max(1,String(text||'').length);progress.value=0;progress.setAttribute('aria-label','تقدم قراءة الشرح');
 const progressLabel=document.createElement('div');progressLabel.className='speech-progress-label';progressLabel.setAttribute('aria-live','polite');progressLabel.textContent='جاهز للاستماع';
 const transcript=document.createElement('div');transcript.className='speech-transcript';transcript.setAttribute('aria-label','نص الشرح مع تمييز الكلمات أثناء القراءة');
 const re=/\s+|[^\s]+/g;let m;while((m=re.exec(text))){const span=document.createElement('span');span.textContent=m[0];span.dataset.start=String(m.index);span.dataset.end=String(m.index+m[0].length);if(/^\s+$/.test(m[0]))span.className='speech-space';else span.className='speech-word';span.classList.add('speech-not-revealed');transcript.appendChild(span)}
 wrap.append(progressLabel,progress,transcript);box.replaceChildren(wrap);return transcript;
}
function revealSpeechThrough(charIndex){document.querySelectorAll('.speech-transcript .speech-word,.speech-transcript .speech-space').forEach(w=>{if(Number(w.dataset.start)<charIndex)w.classList.remove('speech-not-revealed')})}
function highlightSpokenWord(charIndex){const words=document.querySelectorAll('.speech-word');let found=null;for(const w of words){const a=Number(w.dataset.start),b=Number(w.dataset.end);if(charIndex>=a&&charIndex<b){found=w;break}}if(!found)return;revealSpeechThrough(charIndex+1);document.querySelectorAll('.speech-word.is-speaking').forEach(x=>x.classList.remove('is-speaking'));found.classList.add('is-speaking');const transcript=found.closest('.speech-transcript');if(!transcript)return;const wrap=transcript.closest('.speech-player');const progress=wrap?.querySelector('.speech-progress');const label=wrap?.querySelector('.speech-progress-label');const start=Number(found.dataset.start);if(progress)progress.value=start;if(label)label.textContent=`موضع القراءة: ${Math.min(start+1,progress?.max||start+1)} من ${progress?.max||start+1}`;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const top=found.offsetTop-transcript.offsetTop-(transcript.clientHeight-found.offsetHeight)/2;transcript.scrollTo({top:Math.max(0,top),behavior:reduced?'auto':'smooth'});}

async function api(path,data){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const out=await r.json().catch(()=>({}));if(!r.ok)throw Error(out.error||'تعذّر الحفظ');return out}
let parentAuthenticated=false,parentSyncBusy=false;
function profileSnapshot(){return loadProfiles().map(p=>({id:p.id,name:p.name,progress:p.progress||emptyProgress(p.name)}))}
async function syncProfilesToServer(){if(!parentAuthenticated||parentSyncBusy)return;parentSyncBusy=true;try{const r=await fetch('/api/parent/profiles',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({profiles:profileSnapshot()})});const out=await r.json().catch(()=>({}));if(!r.ok)throw Error(out.error||'تعذّر مزامنة ملفات الأطفال');const s=$('#accountStatus');if(s)s.textContent='تم حفظ ملفات الأطفال وتقدّمهم على الخادم.';}catch(e){const s=$('#accountStatus');if(s)s.textContent='تعذّرت المزامنة الآن؛ بيانات الجهاز ما زالت محفوظة محليًا. '+e.message;}finally{parentSyncBusy=false}}
function applyRemoteProfiles(profiles){if(!Array.isArray(profiles)||!profiles.length)return false;const safe=profiles.slice(0,8).map(p=>({id:String(p.id||('child-'+Math.random().toString(36).slice(2,8))),name:String(p.name||'الطفل').slice(0,40),progress:{completed:Array.isArray(p.progress?.completed)?p.progress.completed:[],attempts:Number(p.progress?.attempts)||0,correct:Number(p.progress?.correct)||0,name:String(p.progress?.name||p.name||'').slice(0,40),lessonStats:p.progress?.lessonStats&&typeof p.progress.lessonStats==='object'?p.progress.lessonStats:{},answerHistory:Array.isArray(p.progress?.answerHistory)?p.progress.answerHistory.slice(0,100):[]}}));localStorage.setItem(PROFILES_KEY,JSON.stringify(safe));if(!safe.some(p=>p.id===localStorage.getItem(ACTIVE_PROFILE_KEY)))localStorage.setItem(ACTIVE_PROFILE_KEY,safe[0].id);writeProgress(safe.find(p=>p.id===activeProfileId())?.progress||safe[0].progress);renderProfileControls();renderProgress();return true}
function setAccountUI(auth,email){parentAuthenticated=!!auth;const status=$('#accountStatus');if(status)status.textContent=auth?'تم تسجيل الدخول: '+email+'. ملفات الأطفال تُزامَن مع الخادم عند تغيّرها.':'لم يتم تسجيل الدخول. التقدم محفوظ محليًا على هذا الجهاز فقط.';$('#parentLogin').classList.toggle('hidden',!!auth);$('#parentRegister').classList.toggle('hidden',!!auth);$('#parentLogout').classList.toggle('hidden',!auth);$('#parentPassword').value='';}
async function parentAccount(action){const email=$('#parentEmail').value.trim(),password=$('#parentPassword').value;if(!email||!password){$('#accountStatus').textContent='أدخل البريد الإلكتروني وكلمة المرور.';return}const btn=action==='login'?$('#parentLogin'):$('#parentRegister');btn.disabled=true;try{const out=await api('/api/parent/'+action,{email,password});setAccountUI(true,out.email);if(action==='login'&&Array.isArray(out.profiles)&&out.profiles.length){applyRemoteProfiles(out.profiles);toast('تم استرجاع ملفات الأطفال من حسابك.')}else{await syncProfilesToServer();toast(action==='login'?'تم تسجيل الدخول.':'تم إنشاء حساب ولي الأمر.')} }catch(e){$('#accountStatus').textContent=e.message;}finally{btn.disabled=false}}
async function checkParentSession(){try{const r=await fetch('/api/parent/me');const out=await r.json();if(out.authenticated){setAccountUI(true,out.email);if(Array.isArray(out.profiles)&&out.profiles.length)applyRemoteProfiles(out.profiles);else await syncProfilesToServer();}}catch{}}
$('#parentLogin').addEventListener('click',()=>parentAccount('login'));$('#parentRegister').addEventListener('click',()=>parentAccount('register'));$('#parentAccountForm').addEventListener('submit',e=>{e.preventDefault();parentAccount('login')});$('#parentLogout').addEventListener('click',async()=>{try{await api('/api/parent/logout',{});}catch{}setAccountUI(false,'');});

function formObject(form){return Object.fromEntries(new FormData(form).entries())}
function renderSaved(db){const select=$('#curriculumBookSelect');if(select){const chosen=select.value;select.innerHTML='<option value="">اختر كتابًا من الكتب المقروءة…</option>'+(db.books||[]).filter(b=>b.extractedText&&b.extractedText.length>30).map(b=>`<option value="${esc(b.id)}">${esc(b.title)}${b.grade?' — '+esc(b.grade):''}</option>`).join('');if([...select.options].some(o=>o.value===chosen))select.value=chosen;}$('#bookList').innerHTML=(db.books||[]).length?db.books.map(b=>{const outline=(b.outline||[]);const units=(db.units||[]).filter(u=>u.bookId===b.id);const drafts=(db.lessons||[]).filter(l=>l.sourceBookId===b.id);return `<article class="saved-item curriculum-book"><b>📚 ${esc(b.title)}</b><span>${esc([b.grade,b.subject,b.author].filter(Boolean).join(' · ')||'لم تُضف تفاصيل إضافية')}</span>${b.pdfUploaded?`<p>📄 ${arabicNum(b.pages||0)} صفحة · ${arabicNum(b.extractedChars||0)} حرف مستخرج</p><a class="btn secondary" href="/api/curriculum/pdf/${encodeURIComponent(b.id)}" target="_blank" rel="noopener">فتح ملف PDF</a>${outline.length?`<details open><summary>مراجعة عناوين الوحدات والدروس (${arabicNum(outline.length)})</summary><p>صحّح العناوين أدناه، ثم أنشئ مسودات منظمة. لن تظهر دروس المنهج للطلاب قبل اعتمادها.</p><div class="outline-editor" data-book="${esc(b.id)}">${outline.map((o,i)=>`<label class="outline-row"><span>${arabicNum(i+1)}</span><input data-outline-title value="${esc(o.title)}" maxlength="180" aria-label="عنوان ${arabicNum(i+1)}"></label>`).join('')}<button type="button" class="btn primary" data-organize-book="${esc(b.id)}">إنشاء الوحدات ومسودات الدروس</button><p class="form-status" data-organize-status></p></div></details>`:''}${units.length?`<div class="unit-summary"><b>الوحدات المنشأة: ${arabicNum(units.length)}</b><ul>${units.map(u=>`<li>${esc(u.title)} — مسودة للمراجعة</li>`).join('')}</ul></div>`:''}${drafts.length?`<details open><summary>مراجعة الدروس المستخرجة (${arabicNum(drafts.length)})</summary>${drafts.map(l=>`<div class="draft-review" data-draft="${esc(l.id)}"><label>عنوان الدرس<input data-draft-title value="${esc(l.title)}" maxlength="180"></label><label>محتوى الدرس<textarea data-draft-content rows="5">${esc(l.content)}</textarea></label><p class="form-status">${l.status==='approved'?'معتمد — يظهر للطلاب':'مسودة — لا تظهر للطلاب حتى اعتمادها'}</p><button class="btn primary" type="button" data-approve-lesson="${esc(l.id)}">اعتماد الدرس ونشره</button><button class="btn secondary" type="button" data-save-draft="${esc(l.id)}">حفظ كمسودة</button><p class="form-status" data-review-status></p><div class="quiz-review" data-quiz-review="${esc(l.id)}"><h4>🧩 أسئلة وأنشطة الدرس</h4><p class="form-status">${l.quizStatus==='approved'?'الأسئلة معتمدة وتظهر للطلاب.':(l.quizQuestions||[]).length?'أسئلة مقترحة تحتاج مراجعتك قبل إظهارها للطلاب.':'أنشئ أسئلة مقترحة بعد تفعيل خدمة الذكاء الاصطناعي.'}</p><button type="button" class="btn secondary" data-generate-quiz="${esc(l.id)}">${(l.quizQuestions||[]).length?'إعادة اقتراح الأسئلة':'اقتراح ٣ أسئلة للدرس'}</button><p class="form-status" data-quiz-status></p><div data-quiz-fields>${(l.quizQuestions||[]).map((q,i)=>`<div class="quiz-question" data-quiz-question><b>السؤال ${arabicNum(i+1)}</b><label>نص السؤال<input data-q-text value="${esc(q.question)}" maxlength="500"></label>${q.answers.map((ans,j)=>`<label>الخيار ${arabicNum(j+1)}<input data-q-answer value="${esc(ans)}" maxlength="250"></label>`).join('')}<label>الإجابة الصحيحة<select data-q-correct>${q.answers.map((ans,j)=>`<option value="${j}" ${Number(q.correct)===j?'selected':''}>الخيار ${arabicNum(j+1)}</option>`).join('')}</select></label><p class="form-status">${q.status==='approved'?'معتمد':'مسودة'}</p></div>`).join('')}</div>${(l.quizQuestions||[]).length?`<button type="button" class="btn secondary" data-save-quiz="${esc(l.id)}">حفظ كمسودة</button><button type="button" class="btn primary" data-approve-quiz="${esc(l.id)}">اعتماد الأسئلة ونشرها</button>`:''}</div></div>`).join('')}</details>`:''}<details><summary>معاينة النص المستخرج</summary><p>${esc((b.extractedText||'').slice(0,1800))}${(b.extractedText||'').length>1800?'…':''}</p></details>`:''}</article>`}).join(''):'<div class="empty">لم تُضف كتبًا بعد.</div>';$('#planList').innerHTML=(db.plans||[]).length?db.plans.map(p=>`<article class="saved-item"><b>✎ ${esc(p.title)}</b><span>${esc([p.grade,p.subject].filter(Boolean).join(' · ')||'خطة درس')}</span>${p.objectives?`<p>${esc(p.objectives)}</p>`:''}</article>`).join(''):'<div class="empty">ستظهر خطط الدروس التي تحفظها هنا.</div>';extraLessons=(db.lessons||[]).filter(l=>!l.sourceBookId||l.status==='approved').map(l=>({...l,icon:'📖'}));renderLessons()}
async function refresh(){try{const r=await fetch('/api/content');if(r.ok)renderSaved(await r.json())}catch{toast('تعذّر تحميل البيانات المحفوظة. أعد تحميل الصفحة.')}}

// Public curriculum catalog: download-only for visitors; uploads remain in the admin area.
let publicBooks=[];
function renderPublicBooks(){
 const host=$('#publicBookList');if(!host)return;
 const query=String($('#publicBookSearch')?.value||'').trim().toLocaleLowerCase('ar');
 const grade=String($('#publicBookGrade')?.value||'');const subject=String($('#publicBookSubject')?.value||'');
 const books=publicBooks.filter(b=>b.id&&(b.pdfUploaded===true||Boolean(b.fileName))).filter(b=>!grade||String(b.grade||'')===grade).filter(b=>!subject||String(b.subject||'')===subject).filter(b=>!query||[b.title,b.grade,b.subject,b.author,b.notes,b.term,b.semester].some(v=>String(v||'').toLocaleLowerCase('ar').includes(query)));
 $('#publicBookStatus').textContent=books.length?`الكتب المتاحة للتنزيل: ${arabicNum(books.length)} · اختر الصف ثم المادة ثم الكتاب`:'لم نجد كتابًا مطابقًا. جرّب كلمة أخرى أو غيّر الصف والمادة.';
 if(!books.length){host.innerHTML='<div class="empty">لا توجد كتب PDF منشورة متاحة حاليًا.</div>';return;}
 const byGrade=new Map();
 for(const b of books){const grade=String(b.grade||'صف غير محدد').trim(),subject=String(b.subject||'مواد عامة').trim();if(!byGrade.has(grade))byGrade.set(grade,new Map());const subjects=byGrade.get(grade);if(!subjects.has(subject))subjects.set(subject,[]);subjects.get(subject).push(b);}
 const grades=[...byGrade.keys()].sort((a,b)=>a.localeCompare(b,'ar',{numeric:true}));
 host.innerHTML=grades.map((grade,gi)=>{const subjects=byGrade.get(grade);const count=[...subjects.values()].reduce((n,items)=>n+items.length,0);return `<details class="book-grade" ${gi===0?'open':''}><summary><span class="book-grade-title">📚 ${esc(grade)}</span><span class="book-count">${arabicNum(count)} كتاب</span></summary><div class="book-subject-list">${[...subjects.keys()].sort((a,b)=>a.localeCompare(b,'ar')).map(subject=>{const items=subjects.get(subject).sort((a,b)=>String(a.term||a.semester||'').localeCompare(String(b.term||b.semester||''),'ar',{numeric:true})||String(a.title||'').localeCompare(String(b.title||''),'ar'));return `<details class="book-subject"><summary><span>📘 ${esc(subject)}</span><span class="book-count">${arabicNum(items.length)}</span></summary><div class="book-items">${items.map(b=>`<article class="book-download"><div><b>${esc(b.title||'كتاب منهجي')}</b><span>${esc([b.term||b.semester,b.part?`الجزء ${b.part}`:''].filter(Boolean).join(' · ')||'كتاب المنهج')}</span>${b.pages?`<small>📄 ${arabicNum(b.pages)} صفحة</small>`:''}</div><a class="btn primary" href="/api/public/curriculum/pdf/${encodeURIComponent(b.id)}" download aria-label="تنزيل ${esc(b.title||'الكتاب')}">⬇ تنزيل</a></article>`).join('')}</div></details>`}).join('')}</div></details>`}).join('');
}
async function refreshPublicBooks(){const status=$('#publicBookStatus');if(!status)return;try{const r=await fetch('/api/content',{headers:{'Accept':'application/json'}});if(!r.ok)throw Error('تعذّر تحميل قائمة الكتب');const db=await r.json();publicBooks=Array.isArray(db.books)?db.books:[];if(!Array.isArray(db.books))throw Error('لم تُرجع الخدمة قائمة الكتب بالشكل المتوقع');const fill=(selector,key,label)=>{const el=$(selector);if(!el)return;const previous=el.value;const vals=[...new Set(publicBooks.filter(b=>b.id&&(b.pdfUploaded===true||Boolean(b.fileName))).map(b=>String(b[key]||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ar'));el.innerHTML=`<option value="">${label}</option>`+vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');if(vals.includes(previous))el.value=previous;};fill('#publicBookGrade','grade','كل الصفوف');fill('#publicBookSubject','subject','كل المواد');renderPublicBooks();}catch(e){status.textContent='تعذّر تحميل الكتب الآن. تحقق من الاتصال ثم أعد المحاولة.';const host=$('#publicBookList');if(host)host.innerHTML='<div class="empty">لم نستطع تحميل المكتبة الآن. تحقق من الاتصال ثم اضغط زر إعادة المحاولة.</div>';let retry=$('#retryPublicBooks');if(!retry&&host){retry=document.createElement('button');retry.id='retryPublicBooks';retry.type='button';retry.className='btn secondary';retry.textContent='إعادة تحميل الكتب';retry.addEventListener('click',refreshPublicBooks);host.append(retry)}}}
for(const id of ['publicBookSearch','publicBookGrade','publicBookSubject']){const el=$('#'+id);if(el)el.addEventListener(id==='publicBookSearch'?'input':'change',renderPublicBooks)}
$('#retryPublicBooks')?.addEventListener('click',refreshPublicBooks);

$('#lessonSearch').addEventListener('input',renderLessons);$('#gradeFilter')?.addEventListener('change',e=>{activeGrade=e.target.value;renderLessons()});$$('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderLessons()});$('#menuBtn').onclick=()=>$('#nav').classList.toggle('open');$$('#nav a').forEach(a=>a.onclick=()=>$('#nav').classList.remove('open'));
function uploadDialog(message,kind='info',busy=false){let d=$('#uploadFeedbackDialog');if(!d){d=document.createElement('dialog');d.id='uploadFeedbackDialog';d.className='feedback-dialog';d.innerHTML='<div class="feedback-dialog-inner"><div class="feedback-dialog-icon" aria-hidden="true"></div><h3 class="feedback-dialog-title"></h3><p class="feedback-dialog-message" role="status" aria-live="polite"></p><button type="button" class="btn primary feedback-dialog-close">حسنًا</button></div>';document.body.append(d);d.querySelector('button').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d&&!d.dataset.busy)d.close()})}d.dataset.busy=busy?'1':'';d.querySelector('.feedback-dialog-icon').textContent=busy?'⏳':kind==='success'?'✓':kind==='error'?'!':'ℹ';d.querySelector('.feedback-dialog-title').textContent=busy?'جارٍ تجهيز الكتاب…':kind==='success'?'اكتمل رفع الكتاب':kind==='error'?'تعذّر رفع الكتاب':'حالة الكتاب';d.querySelector('.feedback-dialog-message').textContent=message;d.querySelector('button').classList.toggle('hidden',busy);if(!d.open)d.showModal();if(!busy&&kind==='success')setTimeout(()=>{if(d.open)d.close()},4200);return d}
$('#pdfForm').onsubmit=async e=>{e.preventDefault();const form=e.target;const f=new FormData(form);const file=f.get('pdf');const status=$('#pdfStatus'),result=$('#pdfResult'),btn=$('#pdfUploadBtn');if(!file||!file.size){uploadDialog('اختر ملف PDF أولًا.','error');return}const maxPdfUploadMb=1024;if(file.size>maxPdfUploadMb*1024*1024){uploadDialog('حجم الملف يتجاوز الحد الأعلى المدعوم في الواجهة.','error');return}const grade=String(f.get('grade')||'').trim();const subject=String(f.get('subject')||'').trim();const term=String(f.get('term')||'').trim();const author=String(f.get('author')||'').trim();const notes=String(f.get('notes')||'').trim();if(!subject){uploadDialog('اختر المادة قبل رفع الكتاب.','error');return}const params=new URLSearchParams({title:subject,grade,subject,term,author,notes});btn.disabled=true;btn.textContent='جارٍ رفع الملف واستخراج النص…';status.textContent='';result.classList.add('hidden');uploadDialog('يجري رفع الملف واستخراج النص. لا تغلق الصفحة حتى تنتهي العملية.','info',true);try{const r=await fetch('/api/curriculum/upload?'+params.toString(),{method:'POST',headers:{'Content-Type':'application/pdf'},body:file});const out=await r.json().catch(()=>({}));if(!r.ok)throw Error(out.error||'تعذّر معالجة الكتاب');const message=`تم رفع كتاب ${subject} واستخراج ${arabicNum(out.pages||0)} صفحة بنجاح${out.ocrUsed?' باستخدام OCR':''}.`;status.textContent=message;result.classList.remove('hidden');result.textContent=out.warning||`تم استخراج النص. عناوين أولية: ${out.outlineCount||0}.`;form.reset();await refresh();uploadDialog(message,'success',false)}catch(err){status.textContent=err.message;uploadDialog(err.message,'error',false)}finally{btn.disabled=false;btn.textContent='رفع الملف واستخراج النص'}};

$('#bookList').addEventListener('click',async e=>{
 const organize=e.target.closest('[data-organize-book]');
 if(organize){const wrap=organize.closest('.outline-editor');const status=wrap.querySelector('[data-organize-status]');const outline=[...wrap.querySelectorAll('[data-outline-title]')].map(x=>({title:x.value.trim()})).filter(x=>x.title);organize.disabled=true;status.textContent='جارٍ إنشاء الوحدات ومسودات الدروس…';try{const out=await api('/api/curriculum/organize',{bookId:organize.dataset.organizeBook,outline});status.textContent=`تم إنشاء ${arabicNum(out.unitsCreated)} وحدة و${arabicNum(out.lessonsCreated)} مسودة درس. راجع كل درس قبل اعتماده.`;await refresh()}catch(err){status.textContent=err.message}finally{organize.disabled=false}return;}
 const review=e.target.closest('[data-approve-lesson],[data-save-draft]');if(review){const card=review.closest('[data-draft]');const approve=review.hasAttribute('data-approve-lesson');const id=approve?review.dataset.approveLesson:review.dataset.saveDraft;const status=card.querySelector('[data-review-status]');review.disabled=true;try{await api('/api/curriculum/lessons/'+encodeURIComponent(id)+'/review',{action:approve?'approve':'draft',title:card.querySelector('[data-draft-title]').value,content:card.querySelector('[data-draft-content]').value});status.textContent=approve?'تم اعتماد الدرس؛ سيظهر للطلاب بعد تحديث القائمة.':'تم حفظ التغييرات كمسودة.';await refresh()}catch(err){status.textContent=err.message}finally{review.disabled=false}}
 const gen=e.target.closest('[data-generate-quiz]');
 if(gen){const box=gen.closest('[data-quiz-review]');const status=box.querySelector('[data-quiz-status]');gen.disabled=true;status.textContent='جارٍ إعداد أسئلة مقترحة من نص الدرس…';try{await api('/api/curriculum/lessons/'+encodeURIComponent(gen.dataset.generateQuiz)+'/generate-quiz',{});status.textContent='وصلت الأسئلة المقترحة. راجعها وحدد الإجابة الصحيحة قبل الاعتماد.';await refresh()}catch(err){status.textContent=err.message}finally{gen.disabled=false}return;}
 const saveQuiz=e.target.closest('[data-save-quiz],[data-approve-quiz]');if(saveQuiz){const box=saveQuiz.closest('[data-quiz-review]');const status=box.querySelector('[data-quiz-status]');const questions=[...box.querySelectorAll('[data-quiz-question]')].map((q,i)=>({id:'q-'+i,question:q.querySelector('[data-q-text]').value,answers:[...q.querySelectorAll('[data-q-answer]')].map(x=>x.value),correct:Number(q.querySelector('[data-q-correct]').value)}));const approve=saveQuiz.hasAttribute('data-approve-quiz');saveQuiz.disabled=true;try{await api('/api/curriculum/lessons/'+encodeURIComponent(saveQuiz.dataset.approveQuiz||saveQuiz.dataset.saveQuiz)+'/review-quiz',{action:approve?'approve':'draft',questions});status.textContent=approve?'تم اعتماد الأسئلة ونشرها للطلاب.':'تم حفظ الأسئلة كمسودة.';await refresh()}catch(err){status.textContent=err.message}finally{saveQuiz.disabled=false}return;}
});
