let teacherHistory=[];
let voiceRecognition=null, voiceBusy=false, currentSpeechText='', voiceHoldActive=false, voiceFinalTranscript='', voiceErrorMessage='';
function voiceStatus(message){const el=$('#voiceStatus');if(el)el.textContent=message}
function stopLessonAudio(message='تم إيقاف الصوت.'){if('speechSynthesis'in window)speechSynthesis.cancel();voiceStatus(message)}
function startHoldToTalk(){
 const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!SR){$('#voiceBtn').classList.remove('is-recording');$('#voiceBtn').textContent='🎤 اضغط باستمرار وتحدّث';voiceStatus('التحدث غير مدعوم في هذا المتصفح. اكتب طلبك ثم اضغط «اشرح».');return}
 if(!$('#curriculumBookSelect')?.value){$('#voiceBtn').classList.remove('is-recording');$('#voiceBtn').textContent='🎤 اضغط باستمرار وتحدّث';voiceStatus('اختر كتاب المنهج أولًا، ثم اضغط باستمرار وتحدث.');$('#curriculumBookSelect')?.focus();return}
 if(voiceRecognition){try{voiceRecognition.abort()}catch{}voiceRecognition=null}
 voiceFinalTranscript='';voiceErrorMessage='';voiceHoldActive=true;
 try{
  const rec=new SR();voiceRecognition=rec;rec.lang='ar-YE';rec.interimResults=true;rec.maxAlternatives=1;rec.continuous=true;
  rec.onstart=()=>voiceStatus('🎙️ استمر ضاغطًا وتحدث الآن… ارفع إصبعك عند الانتهاء.');
  rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const part=String(e.results[i]?.[0]?.transcript||'').trim();if(!part)continue;if(e.results[i].isFinal)voiceFinalTranscript=(voiceFinalTranscript+' '+part).trim();else interim=(interim+' '+part).trim()}const shown=(voiceFinalTranscript+' '+interim).trim();if(shown)voiceStatus('🎙️ '+shown+'\nاستمر بالضغط للتحدث، ثم ارفع إصبعك لتنفيذ الطلب.');};
  rec.onerror=e=>{voiceErrorMessage=(e.error==='not-allowed'||e.error==='service-not-allowed')?'اسمح للمتصفح باستخدام الميكروفون.':e.error==='no-speech'?'لم أسمع كلامًا واضحًا. اضغط باستمرار وحاول مرة أخرى.':'تعذّر التقاط الصوت. يمكنك كتابة طلبك بدلًا من ذلك.';};
  rec.onend=()=>{if(voiceRecognition!==rec)return;voiceRecognition=null;const q=voiceFinalTranscript.trim();const shouldSubmit=!voiceHoldActive;voiceHoldActive=false;if(voiceErrorMessage){voiceStatus(voiceErrorMessage);return}if(!shouldSubmit)return;if(!q){voiceStatus('لم ألتقط كلامًا واضحًا. اضغط باستمرار على زر التحدث، وتحدث، ثم ارفع إصبعك.');return}$('#childQuestion').value=q;voiceStatus('تم التقاط طلبك: «'+q+'». جارٍ تنفيذه…');answerQuestion({speakAnswer:true});};
  rec.start();
 }catch{voiceHoldActive=false;voiceRecognition=null;$('#voiceBtn').classList.remove('is-recording');$('#voiceBtn').textContent='🎤 اضغط باستمرار وتحدّث';voiceStatus('تعذّر تشغيل الميكروفون. تحقق من إذنه أو اكتب طلبك.')}
}
function endHoldToTalk(){
 if(!voiceHoldActive)return;voiceHoldActive=false;
 const rec=voiceRecognition;if(rec){voiceStatus('⏳ جارٍ إنهاء التسجيل وتنفيذ طلبك…');try{rec.stop()}catch{voiceRecognition=null;const q=voiceFinalTranscript.trim();if(q){$('#childQuestion').value=q;answerQuestion({speakAnswer:true})}else voiceStatus(voiceErrorMessage||'لم ألتقط كلامًا. حاول مرة أخرى.')}}
}
async function answerQuestion({speakAnswer=true}={}){
 const q=$('#childQuestion').value.trim();if(!q){voiceStatus('اكتب طلبك أو اضغط الميكروفون.');return}
 if(!$('#curriculumBookSelect')?.value){voiceStatus('اختر كتاب المنهج أولًا.');$('#curriculumBookSelect')?.focus();return}
 const btn=$('#askBtn'),box=$('#teacherAnswer');btn.disabled=true;btn.textContent='لحظة…';box.classList.remove('hidden');box.textContent='يحضّر المعلّم الشرح…';voiceStatus('يحضّر المعلّم شرحًا مناسبًا لطلبك…');
 try{
  const r=await fetch('/api/teacher/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q,history:teacherHistory,bookId:$('#curriculumBookSelect').value})});const out=await r.json();if(!r.ok)throw Error(out.error||'تعذّر الحصول على الشرح.');const answer=String(out.answer||'');currentSpeechText=answer;
  renderSpeechTranscript(answer,box);teacherHistory.push({role:'user',content:q},{role:'assistant',content:answer});teacherHistory=teacherHistory.slice(-8);
  const actions=document.createElement('div');actions.className='teacher-followups';
  const add=(label,fn,cls='btn secondary')=>{const b=document.createElement('button');b.type='button';b.className=cls;b.textContent=label;b.addEventListener('click',fn);actions.appendChild(b)};
  add('🔊 أعد الاستماع',()=>{renderSpeechTranscript(currentSpeechText,box);speak(currentSpeechText)},'btn primary');add('⏸️ إيقاف مؤقت',()=>{if(window.speechSynthesis?.speaking)window.speechSynthesis.pause();voiceStatus('توقف الشرح مؤقتًا.')});add('▶️ استكمال',()=>{if(window.speechSynthesis?.paused)window.speechSynthesis.resume();else speak(currentSpeechText)});add('⏹️ إيقاف',()=>stopLessonAudio());
  box.appendChild(actions);
  if(/(?:\d|واحد|اثنان|اثنين|ثلاث|ثلاثة|تفاح|جمع|طرح|ناقص|زائد|يساوي|\+|−|=)/i.test(answer)){const board=document.createElement('div');board.className='visual-learning-board';board.setAttribute('aria-label','تمثيل بصري مبسط');const addGroup=(n,removed=0)=>`<div class="visual-math-group"><span>${Array.from({length:Math.min(10,Number(n)||0)},(_,i)=>i<removed?'🍎̶':'🍎').join(' ')}</span><b>${n}</b></div>`;const plus=answer.match(/(\d+)\s*\+\s*(\d+)\s*=\s*(\d+)/);const minus=answer.match(/(\d+)\s*(?:−|[-])\s*(\d+)\s*=\s*(\d+)/);if(plus){const [_,a,b,c]=plus;board.innerHTML=`${addGroup(a)}<span class="visual-math-op">＋</span>${addGroup(b)}<span class="visual-math-op">＝</span>${addGroup(c)}`;box.insertBefore(board,actions)}else if(minus&&Number(minus[1])<=10&&Number(minus[2])<=Number(minus[1])){const [_,a,b,c]=minus;board.innerHTML=`<div class="visual-math-step"><strong>لدينا ${a} تفاحات</strong>${addGroup(a)}</div><span class="visual-math-op">−</span><div class="visual-math-step"><strong>نزيل ${b}</strong>${addGroup(a,b)}</div><span class="visual-math-op">＝</span><div class="visual-math-step"><strong>يتبقى ${c}</strong>${addGroup(c)}</div>`;box.insertBefore(board,actions)}}
  if(!out.configured)voiceStatus('تم تجهيز معاينة الشرح. لتوليد شرح يفهم أسئلتك بحرية، فعّل خدمة الذكاء الاصطناعي على الخادم.');else voiceStatus('يبدأ الشرح الصوتي الآن. ستُظلّل الكلمات أثناء القراءة إذا كان المتصفح يدعم توقيت الكلمات.');
  if(speakAnswer&&answer){const ok=await speak(answer);if(ok)voiceStatus('انتهى الشرح. يمكنك إعادة الاستماع أو طلب شرح آخر.')}
 }catch(err){box.textContent=err.message;voiceStatus('تعذّر إعداد الشرح. تحقق من الاتصال ثم حاول مجددًا.')}
 finally{btn.disabled=false;btn.textContent='🔊 اشرح';}
}
document.querySelectorAll('[data-student-prompt]').forEach(b=>b.addEventListener('click',()=>{const q=b.dataset.studentPrompt||'';if(/صفحة 1/.test(q)){const page=prompt('اكتب رقم الصفحة التي تريد شرحها:','1');if(page===null)return;$('#childQuestion').value=q.replace('صفحة 1','صفحة '+page.trim())}else $('#childQuestion').value=q;if($('#curriculumBookSelect')?.value)answerQuestion({speakAnswer:true});else voiceStatus('اختر كتاب المنهج أولًا، ثم اضغط طلب الشرح مرة أخرى.')}));
$('#askBtn').addEventListener('click',()=>answerQuestion({speakAnswer:true}));
$('#stopVoiceBtn')?.addEventListener('click',()=>stopLessonAudio());
$('#voiceBtn').textContent='🎤 اضغط باستمرار وتحدّث';
$('#voiceBtn').setAttribute('aria-label','اضغط باستمرار أثناء التحدث، ثم ارفع إصبعك لتنفيذ الطلب');
$('#voiceBtn').style.touchAction='none';
$('#voiceBtn').style.userSelect='none';
$('#voiceBtn').addEventListener('contextmenu',e=>e.preventDefault());
$('#voiceBtn').addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();try{$('#voiceBtn').setPointerCapture(e.pointerId)}catch{}$('#voiceBtn').classList.add('is-recording');$('#voiceBtn').textContent='🔴 استمر بالضغط والتحدث…';startHoldToTalk()});
const releaseVoiceButton=()=>{if(!voiceHoldActive)return;$('#voiceBtn').classList.remove('is-recording');$('#voiceBtn').textContent='🎤 اضغط باستمرار وتحدّث';endHoldToTalk()};
$('#voiceBtn').addEventListener('pointerup',releaseVoiceButton);
$('#voiceBtn').addEventListener('pointercancel',releaseVoiceButton);
$('#voiceBtn').addEventListener('lostpointercapture',releaseVoiceButton);
